function Empty({query,onNew}:{query:string|boolean;onNew:()=>void}){return <div className="empty-state"><div><Mail size={39} strokeWidth={1}/><Heart size={15}/></div><h3>{query?'这一页还没有匹配的片段':'故事，等你写下第一笔。'}</h3><p>{query?'试试其他关键词、标签，或切换到全部档案。':'一段文字，一张照片，都是很好的开始。'}</p>{!query&&<button className="primary-button" onClick={onNew}><Plus size={16}/>新建档案</button>}</div>}
function Lightbox({state,onChange,onClose}:{state:{images:LightImage[];index:number};onChange:(s:{images:LightImage[];index:number})=>void;onClose:()=>void}){
 const item=state.images[state.index];const move=useCallback((n:number)=>onChange({...state,index:(state.index+n+state.images.length)%state.images.length}),[state,onChange]);
 useEffect(()=>{const k=(e:KeyboardEvent)=>{if(e.defaultPrevented||(e.target as Element).closest('[data-image-pan],input,textarea,select'))return;if(e.key==='ArrowLeft')move(-1);if(e.key==='ArrowRight')move(1)};document.addEventListener('keydown',k);return()=>document.removeEventListener('keydown',k)},[move]);
 return <Modal onClose={onClose} label="原图阅读" className="lightbox reader-lightbox"><div className="lightbox-top"><span>{state.index+1} / {state.images.length}</span><span>{item.title}</span><button className="icon-button" aria-label="关闭图片" onClick={onClose}><X size={24}/></button></div><ImageReader key={item.url} src={item.url} title={item.title} full/>{state.images.length>1&&<div className="reader-lightbox-navigation"><button type="button" aria-label="上一张" onClick={()=>move(-1)}><ChevronLeft size={18}/><span>上一张</span></button><div className="reader-lightbox-thumbs">{state.images.map((im,i)=><button key={im.url} className={i===state.index?'active':''} aria-label={`阅读 ${im.title}`} onClick={()=>onChange({...state,index:i})}><img src={im.url} alt="" loading="lazy"/></button>)}</div><button type="button" aria-label="下一张" onClick={()=>move(1)}><span>下一张</span><ChevronRight size={18}/></button></div>}</Modal>
}

